// Enforce marketplace limits and flag anything that needs a human look
return $input.all().map((item, i) => {
  const o = item.json.output || {};
  const req = $('Product photo form').itemMatching(i).json;
  const etsy = (req.platform || '').toLowerCase() === 'etsy';
  const issues = [];
  let title = (o.title || '').trim();
  const max = etsy ? 140 : 70;
  if (title.length > max) { issues.push(`title cut to ${max} chars`); title = title.slice(0, max).replace(/[\s,]+\S*$/, ''); }
  let tags = [...new Set((o.tags || []).map(t => String(t).toLowerCase().trim()).filter(Boolean))];
  if (etsy) {
    const long = tags.filter(t => t.length > 20);
    if (long.length) issues.push(`dropped tags over 20 chars: ${long.join(', ')}`);
    tags = tags.filter(t => t.length <= 20).slice(0, 13);
    if (tags.length < 13) issues.push(`only ${tags.length}/13 tags`);
  }
  if (!o.is_product) issues.push('photo does not look like a product');
  return { json: {
    created_at: $now.toFormat('yyyy-MM-dd HH:mm'), platform: req.platform || '', product_notes: req.product_notes || '',
    photo_filename: req.photo?.filename || '', title, description: o.description || '',
    bullet_points: (o.bullet_points || []).join('\n'), tags: tags.join(', '), seo_title: o.seo_title || '',
    meta_description: o.meta_description || '', alt_text: o.alt_text || '', colors: (o.colors || []).join(', '),
    materials: (o.materials || []).join(', '), status: issues.length ? 'FIX' : 'REVIEW', issues: issues.join('; ')
  } };
});

